import json

# Compare entity and relation counts
with open('outputs/phase2_scierc_full_s1_v2.jsonl') as f:
    baseline = [json.loads(l) for l in f]
with open('outputs/scierc_full_s1_consensus_v2.jsonl') as f:
    consensus = [json.loads(l) for l in f]

# Count differences
diff_count = 0
ent_changes = 0
rel_changes = 0
for b, c in zip(baseline, consensus):
    b_ents = set(tuple(e) if isinstance(e, list) else (e.get('text',''),e.get('type','')) for e in b.get('entities',[]))
    c_ents = set(tuple(e) if isinstance(e, list) else (e.get('text',''),e.get('type','')) for e in c.get('entities',[]))
    b_rels = set()
    c_rels = set()
    for r in b.get('relations',[]):
        if isinstance(r, dict):
            b_rels.add((r.get('head',''),r.get('relation',''),r.get('tail','')))
    for r in c.get('relations',[]):
        if isinstance(r, dict):
            c_rels.add((r.get('head',''),r.get('relation',''),r.get('tail','')))
    if b_ents != c_ents:
        ent_changes += 1
    if b_rels != c_rels:
        rel_changes += 1
    if b != c:
        diff_count += 1

print(f'Total docs: {len(baseline)}')
print(f'Docs with any diff: {diff_count}')
print(f'Docs with entity diff: {ent_changes}')
print(f'Docs with relation diff: {rel_changes}')

# Show first few entity type diffs
type_changes = 0
for b, c in zip(baseline, consensus):
    b_ents = b.get('entities',[])
    c_ents = c.get('entities',[])
    if len(b_ents) == len(c_ents):
        for be, ce in zip(b_ents, c_ents):
            if isinstance(be, dict) and isinstance(ce, dict):
                if be.get('type') != ce.get('type'):
                    type_changes += 1
                    if type_changes <= 5:
                        print(f'  Entity type change: {be[\"text\"]}: {be[\"type\"]} -> {ce[\"type\"]}')
print(f'Total entity type changes: {type_changes}')
